class Solution:
    def numOfPairs(self, nums: List[str], target: str) -> int:
        cnt = {}
        for x in nums:
            cnt[x] = cnt.get(x, 0) + 1
        res = 0
        for k in range(1, len(target)):
            pre, suf = target[:k], target[k:]
            if pre == suf:
                c = cnt.get(pre, 0)
                res += c * (c - 1)
            else:
                res += cnt.get(pre, 0) * cnt.get(suf, 0)
        return res

