class Solution {
public:
    int numOfPairs(vector<string>& nums, string target) {
        unordered_map<string, int> cnt;
        for (auto& x : nums) cnt[x]++;
        int res = 0;
        for (int k = 1; k < (int)target.size(); k++) {
            string pre = target.substr(0, k), suf = target.substr(k);
            if (pre == suf) {
                int c = cnt[pre];
                res += c * (c - 1);
            } else {
                res += cnt[pre] * cnt[suf];
            }
        }
        return res;
    }
};

