class Solution {
    public int numOfPairs(String[] nums, String target) {
        Map<String, Integer> cnt = new HashMap<>();
        for (String x : nums) cnt.merge(x, 1, Integer::sum);
        int res = 0;
        for (int k = 1; k < target.length(); k++) {
            String pre = target.substring(0, k), suf = target.substring(k);
            if (pre.equals(suf)) {
                int c = cnt.getOrDefault(pre, 0);
                res += c * (c - 1);
            } else {
                res += cnt.getOrDefault(pre, 0) * cnt.getOrDefault(suf, 0);
            }
        }
        return res;
    }
}

